import * as React from "react";
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import { DayPicker, getDefaultClassNames, type DayButtonProps } from "react-day-picker";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { iconButtonVariants } from "./icon-button";

/**
 * figma: Calendar — built on react-day-picker.
 *
 * The `Date` component set is 72 variants:
 *   State     Default | Hover/Current | Selected | Focused | Booked | Disabled
 *   Position  Single | Left | Middle | Right      (range edges)
 *   Size      sm 28 | default 38 | lg 48          (measured, square, radius-lg)
 *
 * `Calendar header` is Type = Month | MonthYear | Year, which maps onto
 * react-day-picker's `captionLayout`.
 *
 * Recipes: Basic · Range · Month and Year Selector · Presets · Date and Time
 * Picker · Booked dates · Custom Cell Size · Week Numbers · RTL · Persian /
 * Hijri / Jalali (swap the import for `react-day-picker/persian`).
 */
const dayVariants = cva(
  cn(
    "relative flex aspect-square w-full items-center justify-center text-sm font-normal transition-colors",
    "hover:bg-accent hover:text-accent-foreground",
    "focus-visible:z-10 focus-visible:ring-ring-subtle focus-visible:ring-[3px] focus-visible:outline-none",
    // Selected — single, and both ends of a range.
    "data-[selected-single=true]:bg-primary data-[selected-single=true]:text-primary-foreground",
    "data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground",
    "data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground",
    // Position — the range collapses the inner corners.
    "data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-middle=true]:rounded-none",
    "data-[range-start=true]:rounded-e-none data-[range-end=true]:rounded-s-none",
    // Booked — struck through but still readable.
    "data-[booked=true]:line-through data-[booked=true]:opacity-60",
    "disabled:pointer-events-none disabled:opacity-50"
  ),
  {
    variants: {
      size: { sm: "rounded-lg", default: "rounded-lg", lg: "rounded-lg" },
    },
    defaultVariants: { size: "default" },
  }
);

const cellSize = { sm: "size-7", default: "size-9.5", lg: "size-12" } as const;

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  size = "default",
  buttonVariant = "ghost",
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  size?: "sm" | "default" | "lg";
  /** Variant used for the previous / next month controls. */
  buttonVariant?: "default" | "outline" | "secondary" | "ghost";
}) {
  const defaults = getDefaultClassNames();
  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      captionLayout={captionLayout}
      data-slot="calendar"
      data-size={size}
      className={cn("group/calendar p-3 [--cell-size:--spacing(9.5)]", className)}
      classNames={{
        ...defaults,
        root: cn("w-fit", defaults.root),
        months: cn("relative flex flex-col gap-4 md:flex-row", defaults.months),
        month: cn("flex w-full flex-col gap-4", defaults.month),
        nav: cn("absolute inset-x-0 top-0 flex items-center justify-between gap-1", defaults.nav),
        button_previous: cn(
          iconButtonVariants({ variant: buttonVariant, size: "sm" }),
          "aria-disabled:opacity-50",
          defaults.button_previous
        ),
        button_next: cn(
          iconButtonVariants({ variant: buttonVariant, size: "sm" }),
          "aria-disabled:opacity-50",
          defaults.button_next
        ),
        month_caption: cn("flex h-7 items-center justify-center px-8", defaults.month_caption),
        caption_label: cn("text-sm font-medium select-none", defaults.caption_label),
        dropdowns: cn("flex h-7 items-center justify-center gap-1.5 text-sm font-medium", defaults.dropdowns),
        dropdown_root: cn(
          "relative rounded-md border border-input shadow-xs has-focus:border-ring has-focus:ring-ring-subtle has-focus:ring-[3px]",
          defaults.dropdown_root
        ),
        dropdown: cn("absolute inset-0 bg-popover opacity-0", defaults.dropdown),
        weekdays: cn("flex", defaults.weekdays),
        weekday: cn(
          "flex-1 rounded-md text-[0.8rem] font-normal text-muted-foreground select-none",
          defaults.weekday
        ),
        week: cn("mt-2 flex w-full", defaults.week),
        week_number_header: cn("w-(--cell-size) select-none", defaults.week_number_header),
        week_number: cn("text-[0.8rem] text-muted-foreground select-none", defaults.week_number),
        day: cn(
          "group/day relative aspect-square w-full p-0 text-center select-none",
          cellSize[size],
          defaults.day
        ),
        today: cn("bg-accent text-accent-foreground rounded-lg data-[selected=true]:rounded-none", defaults.today),
        outside: cn("text-muted-foreground aria-selected:text-muted-foreground", defaults.outside),
        disabled: cn("text-muted-foreground opacity-50", defaults.disabled),
        hidden: cn("invisible", defaults.hidden),
        ...classNames,
      }}
      components={{
        Chevron: ({ className: cls, orientation, ...rest }) => {
          const Icon = orientation === "left" ? ChevronLeftIcon : ChevronRightIcon;
          return <Icon className={cn("size-4 rtl:rotate-180", cls)} {...rest} />;
        },
        DayButton: (dayProps) => <CalendarDayButton size={size} {...dayProps} />,
        ...components,
      }}
      {...props}
    />
  );
}

/** One date cell — the Figma `Date` component set. */
function CalendarDayButton({
  className,
  day,
  modifiers,
  size = "default",
  ...props
}: DayButtonProps & VariantProps<typeof dayVariants> & { size?: "sm" | "default" | "lg" }) {
  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus();
  }, [modifiers.focused]);

  return (
    <button
      ref={ref}
      data-day={day.date.toLocaleDateString()}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      data-booked={modifiers.booked}
      className={cn(dayVariants({ size }), className)}
      {...props}
    />
  );
}

export { Calendar, CalendarDayButton, dayVariants };
